package cn.zhuatech.finops.deep;import cn.zhuatech.finops.common.ApiResponse;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/finops-ops") public class DeepDomainController{private final DeepDomainService s;public DeepDomainController(DeepDomainService s){this.s=s;}@GetMapping("/dashboard")ApiResponse<?> dashboard(@RequestParam String organizationCode){return ApiResponse.ok(s.dashboard(organizationCode));}@PostMapping("/accounts")ApiResponse<?> account(@Valid @RequestBody DeepDomainService.AccountRequest r){return ApiResponse.ok(s.account(r));}@PostMapping("/budgets")ApiResponse<?> budget(@Valid @RequestBody DeepDomainService.BudgetRequest r){return ApiResponse.ok(s.budget(r));}@PostMapping("/accounts/{id}/costs")ApiResponse<?> cost(@PathVariable Long id,@Valid @RequestBody DeepDomainService.CostRequest r){return ApiResponse.ok(s.ingest(id,r));}@PostMapping("/accounts/{id}/recommendations")ApiResponse<?> recommend(@PathVariable Long id,@Valid @RequestBody DeepDomainService.RecommendationRequest r){return ApiResponse.ok(s.recommend(id,r));}@PostMapping("/recommendations/{id}/realize")ApiResponse<?> realize(@PathVariable Long id,@Valid @RequestBody DeepDomainService.RealizeRequest r){return ApiResponse.ok(s.realize(id,r));}}
